            # two char rules
            ['root ::= "foo" | "bar"', "f", "1"],
            ['root ::= "foo" | "bar"', "b", "1"],
            ['root ::= "foo" | "bar"', "f", "o1"],
            ['root ::= "foo" | "bar"', "b", "a1"],
            ['root ::= "foo" | "bar"', "f", "ooo"],
            ['root ::= "foo" | "bar"', "b", "arrr"],
            # three char rules
            ['root ::= "foo" | "bar" | "baz"', "f", "1"],
            ['root ::= "foo" | "bar" | "baz"', "f", "z"],
            ['root ::= "foo" | "bar" | "baz"', "b", "b1"],
