            ['root ::= "foo" | "bar" | "baz"', "b", "al"],
            ['root ::= "foo" | "bar" | "baz"', "f", "ooo"],
            ['root ::= "foo" | "bar" | "baz"', "b", "azrr"],
...
            ],
        ],
    )
    def test_it_parses_a_grammar_with_starting_and_additional(
        grammar, starting, additional, expected
    ):
